// Extract email metadata and candidate details
const item = $input.item.json;
const binary = $input.item.binary;

let candidateEmail = item.from ? (item.from.value ? item.from.value[0].address : item.from) : (item.candidate_email || 'candidate@gmail.com');
let candidateName = item.from ? (item.from.value ? item.from.value[0].name : 'Candidate') : (item.candidate_name || 'Candidate');
let subject = item.subject || 'Application for Software Developer';
let resumeText = item.resume_text || '';
let resumeFilename = 'candidate_resume.pdf';

if (binary && binary.attachment_0) {
  resumeFilename = binary.attachment_0.fileName || 'resume.pdf';
}

// Normalize candidate payload
return [{
  json: {
    candidate_name: candidateName,
    candidate_email: candidateEmail,
    application_subject: subject,
    resume_filename: resumeFilename,
    resume_text: resumeText || 'Python Developer with 2 years of experience in FastAPI, SQL, Machine Learning, Pandas, NumPy, and REST API development.',
    job_id: 'python-ml-developer-001',
    received_at: new Date().toISOString()
  }
}];

