const response = $input.item.json;
let rawText = '';

try {
  rawText = response.candidates[0].content.parts[0].text;
} catch (e) {
  rawText = JSON.stringify(response);
}

// Clean markdown formatting (```json ... ```)
rawText = rawText.replace(/```json/g, '').replace(/```/g, '').trim();

let evalData = {};
try {
  evalData = JSON.parse(rawText);
} catch (e) {
  evalData = {
    eligible: false,
    match_score: 50,
    matched_skills: [],
    missing_skills: [],
    reason: "Failed to parse structured JSON from AI response: " + e.message
  };
}

const candidate = $node['Normalize Candidate Data'].json;
const minScore = $node['Load Job Description'].json.minimum_resume_score || 70;
const isEligible = evalData.eligible && (evalData.match_score >= minScore);

return [{
  json: {
    candidate_name: candidate.candidate_name,
    candidate_email: candidate.candidate_email,
    job_id: candidate.job_id,
    resume_score: evalData.match_score || 0,
    eligible: isEligible,
    resume_analysis: evalData,
    resume_text: candidate.resume_text
  }
}];
